hooks.command:
$in = [Console]::In.ReadToEnd() | ConvertFrom-Json
$p = $in.tool_input.file_path
if (-not $p) { $p = $in.tool_response.filePath }
if ($p -and $p.ToString().ToLower().EndsWith('.rs')) {
    $d = Split-Path $p -Parent
    while ($d -and -not (Test-Path (Join-Path $d 'Cargo.toml'))) { $d = Split-Path $d -Parent }
    if ($d) {
        $m = Join-Path $d 'Cargo.toml'
        cargo +nightly fmt --manifest-path $m
        cargo clippy --manifest-path $m --all-targets --quiet
    }
}
